// post.service.ts
@Injectable({ providedIn: 'root' })
export class PostService {
  constructor(private http: HttpClient) {}
  searchPosts(term: string): Observable<any[]> {
    return this.http.get<any[]>(`https://jsonplaceholder.typicode.com/posts?q=${term}`);
  }
}

// search.component.ts
import { Subject } from 'rxjs';
import { debounceTime, distinctUntilChanged, switchMap } from 'rxjs/operators';

@Component({...})
export class SearchComponent implements OnInit {
  searchTerms = new Subject<string>();
  results: any[] = [];

  constructor(private postService: PostService) {}

  ngOnInit() {
    this.searchTerms.pipe(
      debounceTime(300),
      distinctUntilChanged(),
      switchMap(term => this.postService.searchPosts(term))
    ).subscribe(posts => this.results = posts);
  }

  onSearch(term: string) {
    this.searchTerms.next(term);
  }
}

// search.component.html
<input (input)="onSearch($event.target.value)" placeholder="Search posts...">
<ul>
  <li *ngFor="let post of results">{{ post.title }}</li>
</ul>
